/* A single visual system; economic state always comes from LostCargo. */
(function(root){'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const path=id=>'./assets/v04/'+id+'@2x.png';
const art={path,item:(x,cls='item-sprite')=>'<img class="'+cls+'" src="'+(x.shapeId?root.SalvageCargoIdentity.resolve(x).src:path('item_'+x.itemId))+'" alt="" draggable="false">',ship:(id,cls='ship-sprite')=>'<img class="'+cls+'" src="'+path('ship_'+id)+'" alt="'+esc(root.LostCargo.PORT.ships[id]?.name||'飞船')+'" draggable="false">'};
function glyph(name){const shapes={launch:'<path fill="#38304d" d="M15 2h7v7l-4 4h-2v3l-5 5v-7l-3-3H1l5-5h3v-2zM3 16h2v-2h3v2H6v3H3zm0 4h4v2H1v-4h2z"/><path fill="#f4c785" d="M16 5h3v3h-3z"/>',shop:'<path fill="#f4c785" d="M4 5h16l3 6H1z"/><path fill="#a66b55" d="M5 5h3l-1 6H3zm7 0h3l1 6h-4zm7 0h2l2 6h-4z"/><path fill="#9b83ab" d="M3 12h18v10H3z"/><path fill="#242039" d="M6 15h5v7H6zm8 0h4v4h-4z"/>',mission:'<path fill="#f4c785" d="M5 3h14v20H5z"/><path fill="#665778" d="M7 5h10v16H7z"/><path fill="#ecdbc1" d="M9 1h6v5H9zM9 9h1v1H9zm0 4h1v1H9zm0 4h1v1H9zm3-8h4v1h-4zm0 4h4v1h-4zm0 4h4v1h-4z"/>',ship:'<path fill="#f4c785" d="M2 13l6-6h9l5 6v4H3z"/><path fill="#665778" d="M5 12h7v3H5zm9-3h4v5h-4z"/><path fill="#8ecfcf" d="M6 11h4v2H6z"/><path fill="#b6a1bd" d="M9 17h9v3H9z"/>',cargo:'<path fill="#9b83ab" d="M3 7l9-5 9 5v14H3z"/><path fill="#665778" d="M3 8h18v13H3z"/><path fill="#f4c785" d="M10 3h4v6h-4zm-6 14h5v3H4zm11 0h5v3h-5z"/>'};return'<svg viewBox="0 0 24 24" class="pixel-glyph" shape-rendering="crispEdges" aria-hidden="true">'+(shapes[name]||shapes.cargo)+'</svg>';}
function home(s,button){const E=root.LostCargo,m=E.activeMission(s);return '<section class="port-home" aria-label="望潮港主场景"><div class="port-scene" aria-hidden="true"><img class="harbor-bg" src="'+path('harbor_bg')+'" alt=""><span class="docked-ship">'+art.ship(s.fleet.equippedShipId)+'</span><img class="harbor-front" src="'+path('harbor_front')+'" alt=""></div><div class="port-caption"><span>望潮港</span><small>'+esc(E.shipStats(s).name)+' · '+E.capacityCells(s)+'格货舱</small></div><div class="port-shortcuts">'+[['cargo','货舱','cargo'],['shop','商店','shop'],['fleet','飞船','ship'],['missions','任务','mission']].map(([tab,title,g])=>'<button class="port-hotspot hotspot-'+tab+'" data-tab="'+tab+'" aria-label="打开'+title+'">'+(g==='cargo'?art.item({itemId:'metal_crate'}):g==='ship'?art.ship(s.fleet.equippedShipId,'shortcut-ship'):'<img class="item-sprite port-ui-icon" src="./assets/v041/ui_'+(g==='shop'?'shop':'missions')+'@2x.png" alt="">')+'<span>'+title+'</span></button>').join('')+'</div>'+(s.phase==='summary'?returnCard(s,button):'')+'<div class="home-launch">'+(m?'<p class="home-mission">'+glyph('mission')+esc(E.PORT.missions[m.type].name)+' · '+({accepted:'已接取',active:'进行中',complete:'可领取'}[m.status]||m.status)+'</p>':'')+button(glyph('launch')+(s.phase==='summary'?'准备下一趟':'出发'),'depart','primary full launch-cta')+'</div></section>';}
function returnCard(s,b){const E=root.LostCargo,r=E.summaryView(s),m=E.activeMission(s);return'<section class="return-card panel"><header><h2>'+ (r.rescue?'拖航归港':'平安归航')+'</h2><span>'+r.depth+'处航点</span></header><div class="return-stats"><span>带回 <b>'+s.cargo.length+'件</b></span><span>未售货值 <b>'+E.cargoValue(s)+'</b></span><span>现金变动 <b>'+(r.cashDelta>=0?'+':'')+r.cashDelta+'</b></span></div><div class="split">'+b('出售货物 · +'+E.cargoValue(s),'sellAll','primary',!s.cargo.length)+b('补给','shop')+'</div>'+(s.cargo.length?b('看看单件黑市报价','market','full ghost'):'')+(m?.status==='complete'?b('委托已完成 · 查看','missions','full mission-ready'):'')+'<details class="voyage-ledger"><summary>本趟账目</summary><div class="ledger"><span>途中收入</span><b>+'+r.eventIncome+'</b><span>委托已领</span><b>+'+r.reward+'</b><span>本趟货已售</span><b>+'+r.salesCurrent+'</b><span>旧货已售</span><b>+'+r.salesCarried+'</b><span>物资/现场支出</span><b>−'+r.eventSpent+'</b><span>补油/维修</span><b>−'+(r.supplySpent+r.repairSpent)+'</b><span>飞船/设备/扩容</span><b>−'+r.toolSpent+'</b><span>还款</span><b>−'+r.debtPaid+'</b><span>拖航费</span><b>−'+r.rescueFee+'</b></div><p class="note">未售货不算现金。补给、售货与还款由你决定。</p></details></section>';}
function shop(s,b){const E=root.LostCargo;return'<div class="section-head"><h1>港口商店</h1><span class="tag">余额 '+s.money+'</span></div><section class="panel"><h2>燃料与维修</h2>'+[['buyFuel','燃料','fuel','fillFuel'],['repair','耐久','repair','fillHull']].map(([type,label,action,fullAction])=>{const q=E.supplyQuote(s,type,true),small=E.supplyQuote(s,type);return'<div class="supply-item"><header><b>'+label+'</b><span>'+q.from+' → '+q.target+'</span></header><p>'+ (q.amount?'补满 +'+q.amount+' · 共 '+q.cost+' 零件':'已经补满')+'</p><div class="split">'+b('少量 +'+small.amount+' · '+small.cost+'零件',action,'',!small.enabled)+b('一键补满 · '+q.cost+'零件',fullAction,'primary',!q.enabled)+'</div>'+(!q.enabled&&q.amount?'<small>余额不足以补满，少量补给会显示实际数量。</small>':'')+'</div>';}).join('')+'</section><section class="panel"><h2>常规物资</h2>'+Object.entries(E.PORT.products).map(([id,p])=>'<article class="product-row">'+art.item(p)+'<div><b>'+esc(p.name)+'</b><p>'+p.cells+'格 · '+esc(p.effect)+'</p><small>售价 '+p.value+' · 购入 '+p.price+'零件</small></div><button data-product="'+id+'" '+(s.phase!=='port'||s.money<p.price?'disabled':'')+'>购入</button></article>').join('')+'</section>'+b('出售货物 · +'+E.cargoValue(s)+'零件','sellAll','full',!s.cargo.length)+'<div class="spacer"></div>'+b('黑市 · 单件交易','market','full')+b('飞船与升级','fleet','full')+'<p class="note">补给按原单价2零件计算。购买确认后才扣款。</p>';}
function fleet(s,b){const E=root.LostCargo,eq=E.shipStats(s),up=E.cargoUpgradeQuote(s),fu=E.shipUpgradeQuote(s,'fuel'),hu=E.shipUpgradeQuote(s,'hull');
 function upgrade(q,title){return '<article class="ship-upgrade" data-upgrade-kind="'+q.kind+'"><b>'+title+'</b><p class="upgrade-values">'+q.from+(q.cost===null?'':' → '+q.to)+'</p><small>最高 '+q.max+' · '+q.level+'/'+q.levels+'级</small><button data-shipupgrade="'+q.kind+'" '+(!q.enabled?'disabled':'')+'>'+ (q.cost===null?'已升满':'升级 · '+q.cost)+'</button></article>';}
 return '<div class="section-head"><h1>飞船</h1><span class="tag">余额 '+s.money+'</span></div><section class="panel current-ship"><div class="equipped-summary">'+art.ship(eq.id)+'<div><h2>'+esc(eq.name)+'</h2><p>当前飞船 · '+esc(eq.role)+'</p><p>油量 '+s.fuel+'/'+eq.maxFuel+' · 船况 '+s.hull+'/'+eq.maxHull+'</p></div></div><div class="ship-upgrade-grid">'+upgrade(fu,'油箱容量')+upgrade(hu,'耐久上限')+'<article class="ship-upgrade"><b>货舱空间</b><p class="upgrade-values">'+E.capacityCells(s)+(up.cost===null?'':' → '+up.nextCapacity)+'</p><small>最高 '+eq.width*(eq.height+eq.cargoUpgradeCosts.length-eq.cargoLevel)+'格 · '+eq.cargoLevel+'/'+eq.cargoUpgradeCosts.length+'级</small>'+b(up.cost===null?'已扩满':'扩容 · '+up.cost,'upgradeCargo','',!up.enabled)+'</article></div><p class="note">扩油箱不送燃料；加装甲保留原损伤。各船油量、船况分开保存；同一批货物随你换船。</p>'+(E.preparation(s).minimumCost>0?b('需要补给 · 去商店','shop','full'):'')+holdPlan(s)+'<details class="fleet-upgrades"><summary>其他工具</summary>'+b('永久工具','tools','full ghost')+'</details></section><button class="fleet-catalog-entry full" data-act="shipyard"><span>其他飞船</span><small>比较、购买或换装</small><b aria-hidden="true">›</b></button>';}
function shipyard(s,b){const E=root.LostCargo,eq=E.shipStats(s);return '<div class="section-head"><h1>其他飞船</h1><span class="tag">当前 '+esc(eq.name)+'</span></div><div class="ship-catalog">'+Object.entries(E.PORT.ships).filter(([id])=>id!==eq.id).map(([id,spec])=>{const own=s.fleet.ownedShipIds.includes(id),equipped=id===eq.id,st=own?E.shipStats(s,id):{...spec,maxFuel:spec.fuelBase,maxHull:spec.hullBase},c=E.shipComparison(s,id);return '<article class="panel ship-card" data-ship-card="'+id+'"><div class="ship-card-image">'+art.ship(id)+'</div><div class="ship-card-info"><h2>'+esc(spec.name)+'</h2><p>'+spec.role+' · '+st.width*st.height+'格</p><p>油箱 '+st.maxFuel+' / 可升至 '+(spec.fuelBase+spec.fuelStep*spec.fuelUpgradeCosts.length)+'</p><p>耐久 '+st.maxHull+' / 可升至 '+(spec.hullBase+spec.hullStep*spec.hullUpgradeCosts.length)+'</p></div><div class="ship-price"><b>'+ (own?'已拥有':spec.price)+'</b><small>'+ (own?(equipped?'现役':'免费换装'):'零件')+'</small><button '+(own?'data-equip':'data-buyship')+'="'+id+'" class="'+(own?'':'primary')+'" '+(s.phase!=='port'||equipped||!own&&s.money<spec.price?'disabled':'')+'>'+ (equipped?'使用中':own?'换装':s.money<spec.price?'余额不足':'购买')+'</button></div><details class="ship-explanation"><summary>航行特点</summary><p>起步一段耗油 '+c.firstFuel+'；基础船 '+c.starterFirstFuel+'。后续费用看航点报价。</p><p>遇到一次16点碰撞，本船掉 '+c.collision+' 耐久。</p><p>'+ (own?'停泊油量 '+E.shipResources(s,id).fuel+'，船况 '+E.shipResources(s,id).hull+'。':'购入含完整船体，油箱为空；购买不自动换装。')+'</p></details></article>';}).join('')+'</div>';}
function holdPlan(s) {
 const E = root.LostCargo;
 const ship = E.shipStats(s);
 const current = E.Holds.space(ship.id, ship.cargoLevel);
 const nextLevel = Math.min(ship.cargoLevel + 1, ship.cargoUpgradeCosts.length);
 const next = E.Holds.space(ship.id, nextLevel);
 const final = E.Holds.space(ship.id, ship.cargoUpgradeCosts.length);
 let cells = '';
 for (let y = 0; y < final.height; y++) {
  for (let x = 0; x < final.width; x++) {
   const usable = current.usableCellMask[y]?.[x];
   const added = !usable && next.usableCellMask[y]?.[x];
   const future = !usable && !added && final.usableCellMask[y]?.[x];
   const tray = current.fixedTrayCells.some(([tx, ty]) => tx === x && ty === y);
   cells += '<i class="' + (added ? 'unlock-next' : future ? 'unlock-later' : usable ? tray ? 'tray-now' : 'main-now' : 'hull-wall') + '"></i>';
  }
 }
 return '<div class="hold-plan"><div class="hold-plan-grid" aria-hidden="true" style="grid-template-columns:repeat('+final.width+',12px)">'+cells+'</div><div><b>'+esc(current.label)+'</b><p>'+current.capacity+'个有效格'+(nextLevel!==ship.cargoLevel?' → '+next.capacity+'格':' · 结构已扩满')+'</p><small>'+(s.hold.mode==='legacy'?'原装排布仍安全保留，货物可放下后在港口过渡。':nextLevel!==ship.cargoLevel?'亮色为下次扩容新增的固定货台。':'主舱与固定货台共同计入容量。')+'</small></div></div>';
}
function missions(s,b){const E=root.LostCargo,active=E.activeMission(s),labels={accepted:'已接取',active:'进行中',complete:'已完成',claimed:'已领取',abandoned:'已放弃'};return'<div class="section-head"><h1>港口委托</h1><span class="tag">手动接取</span></div><p class="note">同时接取1项，无期限。未接任务也可出发。</p>'+Object.entries(E.PORT.missions).map(([id,m])=>{const current=active?.type===id?active:null,last=[...s.missions].reverse().find(x=>x.type===id),status=current?.status||last?.status;return'<section class="panel mission-card" data-mission-card="'+id+'"><div class="mission-card-heading"><img class="item-sprite port-ui-icon" src="./assets/v041/ui_missions@2x.png" alt=""><h2>'+esc(m.name)+'</h2><span class="tag">'+(status?labels[status]:'可接')+'</span></div><p>'+esc(m.goal)+'</p>'+ (current?.status==='active'?'<p class="mission-progress">航点 '+E.missionProgress(s).nodes+'/'+m.minimumNodes+(m.minimumItems?' · 物资 '+E.missionProgress(s).items+'/'+m.minimumItems:'')+' · 安全归港后结算</p>':'')+'<p class="note">奖励 '+m.reward+' 零件 · 任务槽1 · '+(m.recordBox?'记录箱独立携带，不占货舱':'不额外占货舱')+'</p>'+ (current?.legacyAutoSettlement?'<p class="note">旧版已接取委托，保留原结算权益。</p>':'')+(current?current.status==='complete'?'<button class="primary full" data-claim="'+current.uid+'">领取 '+m.reward+' 零件</button>':'<button class="full" data-abandon="'+current.uid+'">放弃委托</button>':'<button class="primary full" data-accept="'+id+'" '+(active||s.phase!=='port'?'disabled':'')+'>'+ (last?'再次接取':'接取委托')+'</button>')+'</section>';}).join('')+'<details class="panel"><summary>已发生的委托记录</summary>'+[...s.missions].reverse().slice(0,15).map(m=>'<p class="note">#'+m.uid+' '+esc(E.PORT.missions[m.type].name)+' · '+labels[m.status]+'</p>').join('')+'</details>';}
function route(s,selected,disabled){const E=root.LostCargo,I=root.SalvageIcons,v=E.routeView(s),r=s.route.find(x=>x.uid===selected);return'<section class="route-scene-view"><div class="section-head"><h1>航区信号</h1><span class="tag">坐标 '+s.depth+' / 8</span></div><div class="route-space"><div class="route-orbit" aria-hidden="true"></div><span class="route-current">'+art.ship(s.fleet.equippedShipId)+'<small>当前位置 · '+s.depth+'站</small></span>'+s.route.map((n,i)=>{const q=E.quote(s,n);return'<button class="signal-node signal-'+i+' '+(selected===n.uid?'selected':'')+'" data-route-select="'+n.uid+'" aria-pressed="'+(selected===n.uid)+'">'+I.icon(I.routeIcon(n))+'<b>'+esc(n.name)+'</b><small>风险 '+esc(n.risk)+' · 前进 '+q.out+'</small></button>';}).join('')+'</div>'+ (r?(()=>{const q=E.quote(s,r);return'<section class="panel route-detail" data-route-detail="'+r.uid+'"><h2>'+esc(r.name)+'</h2><div class="forecast"><span>前进油<b>'+q.out+'</b></span><span>抵达后返港油<b>'+q.returnCost+'</b></span><span>预留后余油<b>'+q.free+'</b></span></div><details class="route-signal"><summary>信号详情</summary><p class="note">'+esc(r.signal)+'</p></details><button data-travel="'+r.uid+'" class="primary full" '+(!q.enabled||disabled?'disabled':'')+'>确认前往</button></section>';})():'<p class="note">'+(s.route.length?'点一个已知信号查看费用，再决定是否前往。':'本趟已到航区边缘，带着收获回港。')+'</p>')+'<div class="route-actions"><button data-act="cargo">货舱 · '+E.used(s)+'/'+E.capacityCells(s)+'</button><button data-act="'+(s.depth?'home':'abort')+'" '+(disabled?'disabled':'')+'>'+(s.depth?'返港 · '+v.returnCost+'燃料':'取消出发')+'</button></div></section>';}
root.SalvageArt=art;root.SalvagePortView={home,shop,fleet,shipyard,holdPlan,missions,route,glyph};
})(window);
